SELECT 'gongkao', '因果关系', 'kp-xingce-language-cloze-function-word-causal', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "虚词辨析：因果关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "前后句存在引起与被引起的关系。常用关联词：因为...所以...、由于、因此、导致、致使等。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "空格前后存在明确的因果推导逻辑，或者通过“之所以”等引导词寻找对应。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "倒装因果：遇到“之所以...是因为...”，注意果在前、因在后。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "强加因果：前后文其实只是并列或顺承，填入因果词会导致逻辑断裂。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“从而”与“进而”：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“从而”表顺承或因果（导致了一个自然结果），“进而”表递进。如果前后文没有程度加深，绝不能用进而。"}]}]}]}$$ AS jsonb), NULL, '因果关系的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "因果关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_function_word_causal", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
